public with sharing class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {

        if (accountIds == null || accountIds.isEmpty()) {

            return new Map<String, List<Contact>>();

        }

        Map<String, List<Contact>> groupedContacts = new Map<String, List<Contact>>();

        for (Contact c : [SELECT Id, Email, AccountId FROM Contact WHERE AccountId IN :accountIds AND Email != null]) {

            Integer atIndex = c.Email.indexOf('@');

            if (atIndex > 0) {

                String domain = c.Email.substring(atIndex + 1).toLowerCase();

                if (!groupedContacts.containsKey(domain)) {

                    groupedContacts.put(domain, new List<Contact>());

                }

                groupedContacts.get(domain).add(c);

            }

        }

        return groupedContacts;

    }

}
