public with sharing class RecordSearchService {

    /// Exception thrown by this service when a search cannot be performed.
    public static class SearchException extends Exception {}

    /**
     * Executes a parameterized SOQL search on any standard or custom object.
     *
     * @param objectApiName The API name of the object to query (case‑insensitive).
     * @param fields        List of field API names to include in the SELECT clause (excluding Id).
     * @param filters       Map where key is the field API name and value is the filter value
     *                      (String, Boolean, Date, Decimal, Integer, Id, or null). Keys are case‑insensitive.
     * @param orderByField  Field API name to order by (ascending). If blank, no ORDER BY.
     * @param maxRows       Maximum number of rows to return; must be between 1 and 200 inclusive.
     *
     * @return List of SObjects matching the criteria.
     *
     * @throws SearchException When any validation fails or the running user lacks access.
     */
    public static List<SObject> search(String objectApiName,
                                       List<String> fields,
                                       Map<String, Object> filters,
                                       String orderByField,
                                       Integer maxRows) {

        // ----------------------------------------------------------------------
        // 1. Resolve the object type (case‑insensitive)
        // ----------------------------------------------------------------------
        if (objectApiName == null || objectApiName.trim().isEmpty()) {
            throw new SearchException('Object API name cannot be null or empty.');
        }
        String objApi = objectApiName.trim();

        Schema.SObjectType sto = null;
        for (Schema.SObjectType s : Schema.getGlobalDescribe().values()) {
            if (s.getDescribe().getName().equalsIgnoreCase(objApi)) {
                sto = s;
                break;
            }
        }
        if (sto == null) {
            throw new SearchException('Object ' + objApi + ' does not exist.');
        }
        Schema.DescribeSObjectResult d = sto.getDescribe();

        // Verify the running user can read the object
        if (!d.isAccessible()) {
            throw new SearchException('The running user does not have read access to object ' + objApi + '.');
        }

        // ----------------------------------------------------------------------
        // 2. Validate and resolve the requested fields
        // ----------------------------------------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list cannot be null or empty.');
        }

        // Map: original trimmed field name -> exact API name from Describe
        Map<String, String> fieldApiMap = new Map<String, String>();

        for (String f : fields) {
            if (f == null) {
                throw new SearchException('Field name cannot be null.');
            }
            String orig = f.trim();
            if (orig.isEmpty()) {
                throw new SearchException('Field name cannot be empty.');
            }
            String resolved = resolveFieldApi(orig, d);
            // Verify the user has read access (FLS) to this field
            Schema.Field fd = d.fields.getMap().get(resolved);
            if (fd == null || !fd.getDescribe().isAccessible()) {
                throw new SearchException('The running user does not have read access to field ' + resolved + '.');
            }
            fieldApiMap.put(orig, resolved);
        }

        // ----------------------------------------------------------------------
        // 3. Validate filters (if supplied)
        // ----------------------------------------------------------------------
        // Map: original filter key -> exact API name
        Map<String, String> filterFieldApiMap = new Map<String, String>();

        if (filters != null && !filters.isEmpty()) {
            for (String key : filters.keySet()) {
                if (key == null) {
                    throw new SearchException('Filter key cannot be null.');
                }
                String orig = key.trim();
                if (orig.isEmpty()) {
                    throw new SearchException('Filter key cannot be empty.');
                }
                String resolved = resolveFieldApi(orig, d);
                Schema.Field fd = d.fields.getMap().get(resolved);
                if (fd == null || !fd.getDescribe().isAccessible()) {
                    throw new SearchException('The running user does not have read access to filter field ' + resolved + '.');
                }
                // Requirement: a filter field cannot be filtered -> check isFilterable()
                if (!fd.getDescribe().isFilterable()) {
                    throw new SearchException('Field ' + resolved + ' is not filterable and cannot be used in a filter.');
                }
                filterFieldApiMap.put(orig, resolved);
            }
        }

        // ----------------------------------------------------------------------
        // 4. Validate orderByField
        // ----------------------------------------------------------------------
        String resolvedOrderBy = null;
        if (orderByField != null && !orderByField.trim().isEmpty()) {
            String orig = orderByField.trim();
            String resolved = resolveFieldApi(orig, d);
            Schema.Field fd = d.fields.getMap().get(resolved);
            if (fd == null || !fd.getDescribe().isAccessible()) {
                throw new SearchException('The running user does not have read access to order‑by field ' + resolved + '.');
            }
            // Requirement: order‑by field cannot be sorted -> check isSortable()
            if (!fd.getDescribe().isSortable()) {
                throw new SearchException('Field ' + resolved + ' is not sortable and cannot be used for ORDER BY.');
            }
            resolvedOrderBy = resolved;
        }

        // ----------------------------------------------------------------------
        // 5. Validate maxRows
        // ----------------------------------------------------------------------
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // ----------------------------------------------------------------------
        // 6. Build the SELECT clause
        // ----------------------------------------------------------------------
        Set<String> selectSet = new Set<String>();
        selectSet.add('Id');
        for (String resolved : fieldApiMap.values()) {
            selectSet.add(resolved);
        }
        List<String> selectList = new List<String>(selectSet);
        String selectClause = 'SELECT ' + String.join(selectList, ', ');

        // ----------------------------------------------------------------------
        // 7. Build the WHERE clause and collect bind values
        // ----------------------------------------------------------------------
        String whereClause = '';
        Map<String, Object> bindValues = new Map<String, Object>();

        if (filters != null && !filters.isEmpty()) {
            Integer idx = 0;
            for (String key : filters.keySet()) {
                String resolved = filterFieldApiMap.get(key);
                if (resolved == null) continue; // should not happen
                Object val = filters.get(key);
                String placeholder = 'f' + idx; // map key without colon, query uses :placeholder
                whereClause += idx > 0 ? ' AND ' : ' WHERE ';
                whereClause += resolved + ' = :' + placeholder;
                bindValues.put(placeholder, val);
                idx++;
            }
        }

        // ----------------------------------------------------------------------
        // 8. Build ORDER BY clause
        // ----------------------------------------------------------------------
        String orderByClause = '';
        if (resolvedOrderBy != null) {
            orderByClause = ' ORDER BY ' + resolvedOrderBy + ' ASC';
        }

        // ----------------------------------------------------------------------
        // 9. Assemble the full query string
        // ----------------------------------------------------------------------
        String query = selectClause
                       + ' FROM ' + objApi
                       + ' WITH SECURITY_ENFORCED'
                       + whereClause
                       + orderByClause
                       + ' LIMIT ' + String.valueOf(maxRows);

        // ----------------------------------------------------------------------
        // 10. Execute the query respecting sharing and FLS
        // ----------------------------------------------------------------------
        List<SObject> results;
        try {
            if (bindValues.isEmpty()) {
                results = Database.query(query);
            } else {
                results = Database.query(query, bindValues);
            }
        } catch (QueryException qe) {
            throw new SearchException('SOQL query failed: ' + qe.getMessage());
        }

        return results;
    }

    /**
     * Resolves a field name to the exact API name stored in the object's Describe,
     * performing a case‑insensitive comparison.
     *
     * @param fieldName the field name as provided by the caller (may be any case)
     * @param d         the DescribeSObjectResult for the target object
     * @return the exact API name
     * @throws SearchException if the field cannot be found
     */
    private static String resolveFieldApi(String fieldName, Schema.DescribeSObjectResult d) {
        if (fieldName == null || fieldName.trim().isEmpty()) {
            throw new SearchException('Field name cannot be null or empty.');
        }
        String search = fieldName.trim();
        // Iterate through the field describe map
        for (Schema.Field f : d.fields.getMap().values()) {
            if (f.getDescribe().getName().equalsIgnoreCase(search)) {
                return f.getDescribe().getName(); // return exact API name
            }
        }
        // Also try exact match (in case the caller already has the right case)
        if (d.fields.getMap().containsKey(search)) {
            return search;
        }
        throw new SearchException('Field ' + search + ' is not a field of the specified object.');
    }
}
