public with sharing class ContactLookupAction {
    public class Request {
        @InvocableVariable(label = 'Email' required = 'true')
        public String email;
    }

    public class Result {
        @InvocableVariable(label = 'Contact ID')
        public Id contactId;

        @InvocableVariable(label = 'Found')
        public Boolean found;
    }

    @InvocableMethod(label = 'Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        // Collect normalized (trimmed, lowercased) emails for a single SOQL query
        Set<String> searchEmails = new Set<String>();
        for (Request req : requests) {
            if (req.email != null && !req.email.trim().isEmpty()) {
                searchEmails.add(req.email.trim().toLowerCase());
            }
        }

        // One SOQL query: find the earliest CreatedDate contact per email, respecting sharing
        Map<String, Contact> earliestContactByEmail = new Map<String, Contact>();
        if (!searchEmails.isEmpty()) {
            for (Contact c : [SELECT Id, Email, CreatedDate FROM Contact WHERE Email IN :searchEmails]) {
                String normalizedEmail = c.Email.trim().toLowerCase();
                if (!earliestContactByEmail.containsKey(normalizedEmail)) {
                    earliestContactByEmail.put(normalizedEmail, c);
                } else if (c.CreatedDate < earliestContactByEmail.get(normalizedEmail).CreatedDate) {
                    earliestContactByEmail.put(normalizedEmail, c);
                }
            }
        }

        // Build results maintaining the same order as the input requests
        for (Request req : requests) {
            Result res = new Result();
            if (req.email != null && !req.email.trim().isEmpty()) {
                String normEmail = req.email.trim().toLowerCase();
                if (earliestContactByEmail.containsKey(normEmail)) {
                    res.contactId = earliestContactByEmail.get(normEmail).Id;
                    res.found = true;
                } else {
                    res.contactId = null;
                    res.found = false;
                }
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }

        return results;
    }
}
