public class ErpAccountSyncJob implements Queueable {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext ctx) {
        // Attach the finalizer before doing any work
        Database.setFinalizer(ctx, new ErpSyncFinalizer(accountIds, attempt));

        // Prepare accounts for all-or-nothing update
        List<Account> accounts = [SELECT Id FROM Account WHERE Id IN :accountIds];
        for (Account a : accounts) {
            a.Description = 'Synced to ERP';
        }
        // Save all-or-nothing; if any account cannot be saved the exception propagates and the job fails
        Database.update(accounts, true);
    }
}
