public class ErpSyncFinalizer implements Database.Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(Database.FinalizerContext context) {
        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = attempt,
            Status__c = context.isSuccess() ? 'Success' : 'Failed'
        );
        if (!context.isSuccess()) {
            Exception ex = context.getException();
            if (ex != null) {
                jobLog.Error__c = ex.getMessage().length() > 255
                    ? ex.getMessage().substring(0, 255)
                    : ex.getMessage();
            } else {
                jobLog.Error__c = '';
            }
            // Retry up to 3 attempts total
            if (attempt < 3) {
                System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
            }
        }
        insert jobLog;
    }
}
