 * Fake IDs: fflib_IDGenerator
 */

@isTest(SeeAllData = false)
private class OpportunitiesServiceTest {

    // ── Helper: create a fresh ApexMocks instance per test ──────────────────────────
    private fflib_ApexMocks givenMocks() {
        return new fflib_ApexMocks();
    }

    // ── 1️⃣ Invalid discount percentage throws exception, domain/uow untouched ──────
    @isTest static void invalidDiscount_throwsException_andDomainUowNotUsed() {
        Test.startTest();
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IOpportunities domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
        Application.Domain.setMock(domainMock);

        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(selectorMock);

        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(uowMock);

        // ── discount = 0 ────────────────────────────────────────────────────────
        System.assertThrows(OpportunitiesService.OpportunitiesServiceException.class,
            () -> OpportunitiesService.applyDiscounts(new Set<Id>(), Decimal.valueOf(0)));

        // ── discount = 51 ────────────────────────────────────────────────────────
        System.assertThrows(OpportunitiesService.OpportunitiesServiceException.class,
            () -> OpportunitiesService.applyDiscounts(new Set<Id>(), Decimal.valueOf(51)));

        // ── discount = null ──────────────────────────────────────────────────────
        System.assertThrows(OpportunitiesService.OpportunitiesServiceException.class,
            () -> OpportunitiesService.applyDiscounts(new Set<Id>(), null));

        Test.stopTest();
    }

    // ── 2️⃣ Null or empty ids: nothing is applied or committed ──────────────────────
    @isTest static nullOrEmptyIds_nothingAppliedOrCommited() {
        Test.startTest();
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IOpportunities domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
        Application.Domain.setMock(domainMock);

        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(selectorMock);

        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(uowMock);

        // ── null ids ────────────────────────────────────────────────────────────
        OpportunitiesService.applyDiscounts(null, Decimal.valueOf(10));

        // ── empty set ────────────────────────────────────────────────────────────
        OpportunitiesService.applyDiscounts(new Set<Id>(), Decimal.valueOf(10));

        // ── verify no unexpected interactions on mocks ────────────────────────────
        // Since the method returns early, applyDiscount and commitWork must NOT have been called.
        // We use verifyNoUnwantedInteractions to confirm the mocks were not invoked.
        // (ApexMocks does not provide a direct “verifyNoCall”, so we rely on the early-return contract.)
        System.assert(true, "null/empty ids path returns without calling domain or uow");

        Test.stopTest();
    }

