        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(uowMock);

        // ── Fake IDs from fflib_IDGenerator ──────────────────────────────────────
        Id oppId1 = fflib_IDGenerator.generate(Opportunity.sObjectType)[0];
        Id oppId2 = fflib_IDGenerator.generate(Opportunity.sObjectType)[0];
        Set<Id> oppIds = new Set<Id>{ oppId1, oppId2 };

        // ── Configure selector to return two fake Opportunity records ────────────
        List<Opportunity> fakeOpps = new List<Opportunity>{ 
            new Opportunity(Id = oppId1, Name = 'Test Opp 1', Amount = 1000.00),
