public class Application {

    // Four public static fields as specified, typed with fflib factory interfaces
    public static fflib_Application.UnitOfWorkFactory UnitOfWork;
    public static fflib_Application.ServiceFactory Service;
    public static fflib_Application.SelectorFactory Selector;
    public static fflib_Application.DomainFactory Domain;

    static {
        // ---------------------------------------------------------
        // UnitOfWork: configured for Account, Contact, Opportunity,
        //             and OpportunityContactRole so a single commit
        //             can insert new records of these types and
        //             register all relationships through the unit of work.
        // ---------------------------------------------------------
        UnitOfWork = new fflib_Application.UnitOfWorkFactory(
            Account.SObjectType,
            Contact.SObjectType,
            Opportunity.SObjectType,
            OpportunityContactRole.SObjectType
        );

        // ---------------------------------------------------------
        // Service: IAccountsService is implemented by AccountsServiceImpl.
        // ---------------------------------------------------------
        Service = new fflib_Application.ServiceFactory(
            IAccountsService.class,
            AccountsServiceImpl.class
        );

        // ---------------------------------------------------------
        // Selector: Account records selected by AccountsSelector,
        //           Contact records selected by ContactsSelector.
        // ---------------------------------------------------------
        Selector = new fflib_Application.SelectorFactory(
            AccountsSelector.class,
            ContactsSelector.class
        );

        // ---------------------------------------------------------
        // Domain: Account records wrapped by the Accounts domain.
        //         Building a domain from a Set<Id> queries records
        //         through the Selector factory configured above.
        // ---------------------------------------------------------
        Domain = new fflib_Application.DomainFactory(
            Accounts.class,
            AccountsSelector.class
        );
    }
}
