public with sharing class Opportunities extends fflib_SObjectDomain<Opportunity> {

    public Opportunities(Opportunity[] records) {
        super(records);
    }

    // Standard inner class implementing fflib_SObjectDomain.IConstructable
    // so the fflib library can build domain instances from SOQL results.
    public class Constructor implements fflib_SObjectDomain.IConstructable {

        public Opportunity construct(Map<Id, SObject> records, SObject record) {
            // Default CloseDate to today + 30 days only if not already set
            if (record.get(Opportunity.CloseDate) == null) {
                record.put(Opportunity.CloseDate, System.today().addDays(30));
            }
            // Default Type to 'New Customer' only if not already set
            if (record.get(Opportunity.Type) == null) {
                record.put(Opportunity.Type, 'New Customer');
            }
            return (Opportunity) record;
        }
    }
}
