public class Accounts extends fflib_SObjects implements IAccounts {
    private final List<Account> records;

    public Accounts(List<Account> records) {
        this.records = records;
    }

    // Inner class Constructor for the domain factory
    public class Constructor {
        public static IAccounts newInstance(List<Account> records) {
            return new Accounts(records);
        }
    }

    // Static factory methods built through Application.Domain factory
    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newInstance(records);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        List<Account> records = Application.Selector.getById(accountIds);
        return (IAccounts) Application.Domain.newInstance(records);
    }

    // fflib_SObjects override
    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public Schema.SObjectType getType() {
        return Account.SObjectType;
    }

    // IAccounts implementation
    public List<Account> getAccounts() {
        return records;
    }

    public IAccounts selectByRating(String rating) {
        List<Account> filtered = new List<Account>();
        for (Account a : records) {
            if (a.Rating == rating) {
                filtered.add(a);
            }
        }
        return new Accounts(filtered);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ids = new Set<Id>();
        for (Account a : records) {
            if (a.OwnerId != null) {
                ids.add(a.OwnerId);
            }
        }
        return ids;
    }

    public void setRating(String rating) {
        for (Account a : records) {
            a.Rating = rating;
        }
    }
}
