    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Build the SELECT clause from the selector's field list
        List<Schema.SObjectField> fieldList = getSObjectFieldList();

        // Build the string of field names using the selector's field list
        String selectFields = '';
        for (Schema.SObjectField f : fieldList) {
            if (!String.isBlank(selectFields)) {
                selectFields += ', ';
            }
            selectFields += f.getDescribe().getName();
        }
        // Add the parent account's Name to the field list
        selectFields += ', Account.Name';

        // Build the full SOQL query using the selector's field list,
        // respecting security settings (inherited sharing) and the query factory pattern
        String query = 'SELECT ' + selectFields +
                       ' FROM Opportunity ' +
                       'WHERE AccountId IN :accountIds AND IsClosed = false ' +
                       'ORDER BY Amount DESC NULLS LAST, CloseDate ASC ' +
                       'LIMIT :maxRecords';

        // Execute the query; the bind variables are resolved from the method parameters
        return (List<Opportunity>) Database.query(query);
    }
