        // Base fields required for the selector
        List<Schema.SObjectField> fieldList = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        // Dynamically include fields from the Credit_Review field set.
        // Admins can add fields to this field set without code changes;
        // this loop picks them up automatically, so we do not hard-code AnnualRevenue or Rating.
        for (Schema.FieldSetMember fsm : Schema.Account.FieldSets.Credit_Review.getFields()) {
            fieldList.add(fsm.getField());
        }

        return fieldList;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        // Build the contact subquery fields from the existing ContactsSelector
        // so it uses that selector's fields (Id, FirstName, LastName, Email, AccountId).
        List<Schema.SObjectField> contactFields = new ContactsSelector().getSObjectFieldList();
        String subqueryFields = String.join(
            contactFields.map(f -> f.getDescribe().getName()), 
            ', '
        );

        // Build the main query field list from the selector's field list
        List<Schema.SObjectField> fieldList = getSObjectFieldList();
        String fieldNames = String.join(
            fieldList.map(f -> f.getDescribe().getName()), 
            ', '
        );

        // Construct the SOQL query with a Contacts child subquery and user mode enforcement
        String query = 'SELECT ' + fieldNames + ' FROM Account WHERE Id IN :accountIds '
                     + '(SELECT ' + subqueryFields + ' FROM Contacts) WITH USER_MODE';

        return (List<Account>) Database.query(query);
    }
