public with sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load the opportunities using the selector
        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Build a map for quick lookup and identify those not already Closed Won
        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName != 'Closed Won') {
                toClose.add(opp);
            }
        }

        // If there is nothing to close, return 0
        if (toClose.isEmpty()) {
            return 0;
        }

        // Set StageName and CloseDate for the opportunities we will close
        Date today = Date.today();
        for (Opportunity opp : toClose) {
            opp.StageName = 'Closed Won';
            opp.CloseDate = today;
        }

        // Obtain one fflib unit of work from the Application factory
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.startWork();

        try {
            // Register the opportunity updates as dirty records
            for (Opportunity opp : toClose) {
                uow.registerDirty(opp);
            }

            // Register a Deal_Won__e event for each opportunity we are closing
            for (Opportunity opp : toClose) {
                Deal_Won__e event = new Deal_Won__e(
                    Opportunity_Id__c = opp.Id,
                    Amount__c = opp.Amount
                );
                uow.registerEvent(event);
            }

            // Commit the unit of work once; this will DML the opportunities
            // and publish the events (because of Publish Immediately behaviour).
            uow.commit();
        } catch (Exception e) {
            // If committing fails, no events are published; rethrow the exception
            // so the caller sees the failure and no Deal_Won__e events leak.
            throw e;
        }

        // Return the number of opportunities that were closed
        return toClose.size();
    }
}
