public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        if (contactIds == null || contactIds.isEmpty()) {
            return new Map<Id, String>();
        }

        // Fetch only the fields we need to keep governor limits friendly
        Map<Id, Contact> contactMap = new Map<Id, Contact>([
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        // Track which contacts originally had a phone value so we only DML those
        Set<Id> contactsWithPhone = new Set<Id>();

        for (Contact c : contactMap.values()) {
            if (c.Phone != null) {
                contactsWithPhone.add(c.Id);
                // Remove every character that is not a digit or a leading plus sign
                c.Phone = c.Phone.replaceAll('[^0-9+]', '');
            }
        }

        // Build the update list from only the contacts that had a phone
        List<Contact> toUpdate = new List<Contact>();
        for (Id id : contactsWithPhone) {
            toUpdate.add(contactMap.get(id));
        }

        // Bulk DML with allOrNone=false so a single failure doesn't block the rest
        if (!toUpdate.isEmpty()) {
            Database.SaveResult[] results = Database.update(toUpdate, false);

            Map<Id, String> errorMap = new Map<Id, String>();

            for (Database.SaveResult sr : results) {
                if (!sr.isSuccess()) {
                    // Capture the first error message only
                    for (Database.Error err : sr.getErrors()) {
                        errorMap.put(sr.getId(), err.getMessage());
                        break;
                    }
                }
            }
            return errorMap;
        }

        // All saved successfully (or nothing needed updating)
        return new Map<Id, String>();
    }
}
