public class PipelineSummary {

    // The four exact stage names sales ops manages
    private static final List<String> STAGE_NAMES = new List<String> {
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Returns the total Amount per stage for opportunities closing between fromDate and toDate (inclusive).
     * Stages with no matching opportunities map to 0, never null.
     *
     * @param fromDate lower bound of CloseDate (inclusive)
     * @param toDate   upper bound of CloseDate (inclusive)
     * @return Map of stage name -> total Amount (0 if no opportunities)
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        for (String stageName : STAGE_NAMES) {
            Decimal sum = 0;
            // One aggregate query per stage – total of 4 queries regardless of data volume
            List<AggregateResult> results = [
                SELECT SUM(Amount) sumAmt
                FROM Opportunity
                WHERE StageName = :stageName
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ];

            if (!results.isEmpty()) {
                Object val = results[0].get('sumAmt');
                if (val != null) {
                    sum = (Decimal) val;
                }
            }
            totals.put(stageName, sum);
        }

        return totals;
    }
}
