public class ErpCustomerSync {

    public static void send(Account a) {
        // Build the JSON payload for a single customer
        Map<String, Object> customer = new Map<String, Object> {
            'salesforceId' => a.Id,
            'name'         => a.Name,
            'country'      => a.BillingCountry
        };

        // Serialize as a JSON array containing one customer object
        String json = JSON.serialize(new List<Object> { customer });

        // Prepare the HTTP request using the Named Credential `ERP`
        HttpRequest req = new HttpRequest();
