import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    @api recordId;

    connectedCallback() {
        super.connectedCallback();
        this.generateCasesUrl();
    }

    generateCasesUrl() {
        const pageReference = {
            objectApiName: 'Case',
            action: 'list',
            state: {
                filterName: 'My_Open_Cases'
            }
        };

        this[NavigationMixin.generateUrl]({ pageReference })
            .then((url) => {
                const link = this.template.querySelector('.cases-link');
                if (link) {
                    link.href = url;
                }
            })
            .catch((error) => {
                console.error('Error generating Case list URL:', error);
            });
    }

    handleClick(event) {
        const action = event.target.dataset.action;
        if (action === 'new-contact') {
            const pageReference = {
                objectApiName: 'Contact',
                action: 'new',
                state: {
                    defaultFieldValues: encodeDefaultFieldValues({ AccountId: this.recordId })
                }
            };
            this[NavigationMixin.navigate](pageReference);
        } else if (action === 'contacts') {
            this[NavigationMixin.navigate]({
                type: 'standard__relatedList',
                attributes: {
                    objectApiName: 'Contact',
                    parentRecordId: this.recordId
                }
            });
        } else if (action === 'edit') {
            const pageReference = {
                objectApiName: 'Account',
                action: 'edit',
                id: this.recordId
            };
            this[NavigationMixin.navigate](pageReference);
        }
    }
}
